const PIRATES_START_AT=Date.parse('2026-09-23T00:00:00+03:00');
const PIRATES_END_AT=Date.parse('2026-09-30T23:59:59+03:00');
const PIRATES_SCHEDULE='23 SEP 00:00 — 30 SEP 23:59 · MSK';
function piratesPhase(now=Date.now()){return now<PIRATES_START_AT?'coming':now>PIRATES_END_AT?'ended':'active'}
function piratesTileSubtitle(){let p=piratesPhase();return p==='coming'?'COMING SOON · 23 SEP 00:00 MSK':p==='ended'?'EVENT ENDED · 30 SEP 23:59 MSK':'LIVE NOW · ENDS 30 SEP 23:59 MSK'}
function piratesGateMarkup(){let p=piratesPhase();if(p==='active')return '';let coming=p==='coming';return `<section class="pirates-time-gate ${p}"><span class="eyebrow">${coming?'COMING SOON':'EVENT ENDED'}</span><h2>${coming?'The cursed fleet arrives September 23.':'The cursed sea has gone quiet.'}</h2><p>${coming?'Cursed Mirror unlocks automatically at 00:00 Moscow time.':'Cursed Mirror closed automatically at 23:59 Moscow time on September 30.'}</p><strong>${PIRATES_SCHEDULE}</strong></section>`}
