  function tradeOffersForTab(){const me=Number(state.liveProfile?.id||0);if(state.tradeTab==='Incoming')return state.liveTrades?.incoming?.offers||[];if(state.tradeTab==='Market')return state.liveTrades?.market?.offers||[];const mine=state.liveTrades?.my?.offers||[];if(state.tradeTab==='Outgoing')return mine.filter(o=>Number(o.creator_user_id)===me&&o.status==='open');return mine.filter(o=>o.status!=='open')}
